[meta]
name = Harrowmere
ambient = 0.25 0.24 0.29
fog = 0.14 0.14 0.19
fog_range = 8 40
model_range = 36
sky = dusk
torch = 4 0.55 0.5 0.45
start = 2 29 0
default = ,
edge_top = -0.5
open_sea = true
entity_floor = auto

// Harrowmere climbs from its harbour to the cathedral on the hill under a low, darkening dusk, a walled
// town of stone and half-timbered houses under steep violet-slate roofs, witch-hatted turrets on their
// corners and round towers along its wall, all stone underfoot: cobbles, setts and flags. The
// cemetery's gate in the west wall, shut behind each Ashen who comes through it; the pier, the quay,
// the canal running up from the harbour and the market lanes; the Bell Square at the heart of town
// with the Silent Bell on its plinth; the sunken court of the old well (down into the Sunken Keep) east of it, and the watch
// house by the gap in the wall where the green trail leaves for the cave; Brannoc's forge and
// Corvane's hut to the west; the north road winding up past Odrin's house to the gate; and up the
// steps on the hill, the cathedral, where the Enthroned sits at the end of the nave.

[legend]
R = wall tex=rough_stone top=7 cap=rough_stone dress=rampart
A = wall tex=cliff_rock top=6 cap=rough_stone
H = wall tex=ashlar top=5.6 cap=roof thin=0.5
J = wall tex=timber top=5.6 cap=roof thin=0.5
C = wall tex=rough_stone h=2 top=11 cap=slate
P = wall tex=flagstone top=0.8 cap=flagstone
_ = wall tex=rough_stone top=2.2 cap=cobble
, = floor tex=cobble h=0
. = floor tex=cobble h=0
s = floor tex=setts h=0
q = floor tex=cobble h=0
- = floor tex=setts h=0
; = floor tex=flagstone h=2 side=rough_stone
= = floor tex=flagstone h=2 side=rough_stone
4 = floor tex=flagstone h=1.6 side=rough_stone
3 = floor tex=flagstone h=1.2 side=rough_stone
2 = floor tex=flagstone h=0.8 side=rough_stone
1 = floor tex=flagstone h=0.4 side=rough_stone
n = floor tex=flagstone h=2 ceil=10 ceil_tex=slate side=rough_stone dark=0.3
a = floor tex=flagstone h=2.4 ceil=10 ceil_tex=slate side=rough_stone dark=0.3
i = floor tex=wood_plank h=0.2 ceil=3.4 ceil_tex=wood_plank side=wood_plank
k = floor tex=flagstone h=0 ceil=3.4 ceil_tex=wood_plank side=rough_stone
o = floor tex=cobble h=-0.8 side=rough_stone
5 = floor tex=cobble h=-0.4 side=rough_stone
p = floor tex=wood_plank h=0.1 side=wood_plank
// The open sea off the quays and the pier is deep: whoever goes in drowns. The canal (r) runs
// shallow between its banks and only casts you back ashore.
~ = water tex=water h=-0.8 side=rough_stone deep
r = water tex=water h=-0.8 side=rough_stone
G = wall tex=vine_wall top=3.4 cap=canopy
V = wall tex=vine_wall top=5.5 cap=canopy
w = floor tex=jungle_floor h=0 ceil=4.2 ceil_tex=canopy side=vine_wall dark=0.2
y = floor tex=jungle_floor h=0 ceil=3.8 ceil_tex=canopy side=vine_wall dark=0.4
v = floor tex=jungle_floor h=0
c = floor tex=rough_stone h=0 ceil=3.4 ceil_tex=cliff_rock side=cliff_rock dark=0.45

